import{_ as a,C as o,o as i,c as r,E as s,a2 as d}from"./chunks/framework.DzI0iiKn.js";const l="/xuexitong-tutorial/images/edge-version1.png",n="/xuexitong-tutorial/images/edge-version2.png",p="/xuexitong-tutorial/images/zhantielinks.png",c="/xuexitong-tutorial/images/edge-driver.png",g="/xuexitong-tutorial/images/chromedriver.png",h="/xuexitong-tutorial/images/copy.png",m="/xuexitong-tutorial/images/select-driver1.png",u="/xuexitong-tutorial/images/select-driver2.png",_="/xuexitong-tutorial/images/select-driver3.png",P=JSON.parse('{"title":"三、如何安装正确的驱动","description":"","frontmatter":{"title":"三、如何安装正确的驱动"},"headers":[],"relativePath":"guide/driver.md","filePath":"guide/driver.md","lastUpdated":1792075685000}'),b={name:"guide/driver.md"};function x(v,e,k,f,E,q){const t=o("PageHero");return i(),r("div",null,[s(t,{index:"03",icon:"🧩",title:"如何安装正确的驱动",subtitle:"Edge / Chrome 驱动下载与配置，解决浏览器相关报错"}),e[0]||(e[0]=d('<p>如果在选择默认的“不指定浏览器”的情况下开始刷课，出现了报错，可以更换浏览器，选择 Edge 或者谷歌浏览器：</p><ul><li>选择 <strong>Edge</strong> 浏览器后，会自动填充驱动地址；</li><li>选择 <strong>谷歌浏览器</strong> 时不会自动填充，需要手动下载谷歌驱动；</li><li>若选择 Edge 后仍报错，同样需要重新下载 Edge 驱动。</li></ul><p>接下来将分别介绍如何下载 Edge 和谷歌浏览器的驱动，并配置到刷课脚本中。</p><h2 id="_1-下载-edge-的驱动" tabindex="-1">1. 下载 Edge 的驱动 <a class="header-anchor" href="#_1-下载-edge-的驱动" aria-label="Permalink to &quot;1. 下载 Edge 的驱动&quot;">​</a></h2><h3 id="_1-1-查看浏览器版本号" tabindex="-1">1.1 查看浏览器版本号 <a class="header-anchor" href="#_1-1-查看浏览器版本号" aria-label="Permalink to &quot;1.1 查看浏览器版本号&quot;">​</a></h3><p>首先打开 Edge 浏览器，点击右上角三个点，再点击<strong>设置</strong>，然后在设置页面点击<strong>关于 Microsoft Edge</strong>，再查看版本号。</p><p><img src="'+l+'" alt="查看 Edge 版本号" loading="lazy"></p><p><img src="'+n+'" alt="查看 Edge 版本号" loading="lazy"></p><h3 id="_1-2-下载对应版本驱动" tabindex="-1">1.2 下载对应版本驱动 <a class="header-anchor" href="#_1-2-下载对应版本驱动" aria-label="Permalink to &quot;1.2 下载对应版本驱动&quot;">​</a></h3><p>然后在导航栏粘贴这个链接：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://developer.microsoft.com/zh-tw/microsoft-edge/tools/webdriver?form=MA13KL#downloads</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p><img src="'+p+'" alt="粘贴链接" loading="lazy"></p><p>按回车键进入到驱动下载网页，根据浏览器的版本号，并依照你的电脑系统（通常为 <code>x64</code>），点击对应的 <code>x64</code> 按钮即可开始下载。</p><p><img src="'+c+'" alt="Edge 驱动下载页面" loading="lazy"></p><div class="tip custom-block"><p class="custom-block-title">版本要对应</p><p>驱动的大版本号必须和浏览器版本号<strong>前三位一致</strong>，否则启动时依然会报错。</p></div><h2 id="_2-下载谷歌驱动" tabindex="-1">2. 下载谷歌驱动 <a class="header-anchor" href="#_2-下载谷歌驱动" aria-label="Permalink to &quot;2. 下载谷歌驱动&quot;">​</a></h2><h3 id="_2-1-查看版本号" tabindex="-1">2.1 查看版本号 <a class="header-anchor" href="#_2-1-查看版本号" aria-label="Permalink to &quot;2.1 查看版本号&quot;">​</a></h3><p>先查看谷歌浏览器的版本号，操作步骤和 Edge 浏览器一样。</p><h3 id="_2-2-下载对应版本驱动" tabindex="-1">2.2 下载对应版本驱动 <a class="header-anchor" href="#_2-2-下载对应版本驱动" aria-label="Permalink to &quot;2.2 下载对应版本驱动&quot;">​</a></h3><p>然后在导航栏粘贴这个链接：</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>https://googlechromelabs.github.io/chrome-for-testing/</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><div class="tip custom-block"><p class="custom-block-title">提示</p><p>若无法访问，可能需要开启加速器。</p></div><p>同样根据自己浏览器的版本，找到相应的驱动。页面下方表格中，请选择名称为 <code>chromedriver</code> 的项，并根据你的系统（通常为 <code>win64</code>）复制对应的链接，打开该链接就会开始下载谷歌驱动。</p><p><img src="'+g+'" alt="谷歌驱动下载页面" loading="lazy"></p><h2 id="_3-解压驱动" tabindex="-1">3. 解压驱动 <a class="header-anchor" href="#_3-解压驱动" aria-label="Permalink to &quot;3. 解压驱动&quot;">​</a></h2><p>下载完成后，对压缩包进行解压，打开解压后的文件夹，复制上方的地址。</p><p><img src="'+h+'" alt="复制上方地址" loading="lazy"></p><h2 id="_4-在脚本中选择驱动" tabindex="-1">4. 在脚本中选择驱动 <a class="header-anchor" href="#_4-在脚本中选择驱动" aria-label="Permalink to &quot;4. 在脚本中选择驱动&quot;">​</a></h2><p>返回到脚本窗口，在设置页面选择 Edge 或谷歌浏览器，点击“选择文件”，将刚刚复制的驱动地址粘贴到地址栏中并回车，然后双击其中的驱动应用程序：</p><table tabindex="0"><thead><tr><th>浏览器</th><th>需要选择的文件</th><th>常见系统版本</th></tr></thead><tbody><tr><td>Edge</td><td><code>msedgedriver.exe</code></td><td><code>x64</code></td></tr><tr><td>Chrome</td><td><code>chromedriver.exe</code></td><td><code>win64</code></td></tr></tbody></table><p><img src="'+m+'" alt="选择驱动" loading="lazy"></p><p><img src="'+u+'" alt="选择驱动" loading="lazy"></p><p><img src="'+_+'" alt="选择驱动" loading="lazy"></p><h2 id="_5-保存设置" tabindex="-1">5. 保存设置 <a class="header-anchor" href="#_5-保存设置" aria-label="Permalink to &quot;5. 保存设置&quot;">​</a></h2><p>修改好后，保存设置。</p><div class="warning custom-block"><p class="custom-block-title">别忘了这一步</p><p>保存后建议先关闭脚本再重新打开，让新的驱动配置生效。</p></div><hr>',37))])}const z=a(b,[["render",x]]);export{P as __pageData,z as default};
